 @objc func changeTab(){exportView.isHidden=tabs.selectedSegment != 0;editView.isHidden=tabs.selectedSegment != 1;if tabs.selectedSegment==1 && songs.isEmpty && !busy{loadLibrary()}}
 func numberOfRows(in tableView:NSTableView)->Int{return songs.count}
 func tableView(_ tableView:NSTableView,viewFor tableColumn:NSTableColumn?,row:Int)->NSView?{let v=NSTextField(labelWithString:songs[row]["title"] as? String ?? "Untitled");v.textColor = .white;v.font=NSFont.systemFont(ofSize:13);v.lineBreakMode = .byTruncatingTail;return v}
 func tableViewSelectionDidChange(_ notification:Notification){let row=songTable.selectedRow;guard row>=0 && row<songs.count else{return};selectedSong=songs[row];images=[];removedImages=[];renderEdit()}
 func renderEdit(){guard let song=selectedSong else{return};editTitle.stringValue=song["title"] as? String ?? "Untitled";editNotes.string=song["notes"] as? String ?? "";editLesson.stringValue=song["lessonUrl"] as? String ?? "";updateImages();refresh()}
 func updateImages(){
  let saved=selectedSong?["images"] as? [[String:Any]] ?? [];let selected=savedImages.selectedItem?.representedObject as? String;savedImages.removeAllItems()
  for (index,image) in saved.enumerated(){guard let id=image["id"] as? String,!removedImages.contains(id) else{continue};savedImages.addItem(withTitle:"\(index+1). "+(image["name"] as? String ?? "Image"));savedImages.lastItem?.representedObject=id}
  if let selected=selected,let item=savedImages.itemArray.first(where:{$0.representedObject as? String == selected}){savedImages.select(item)}
  if savedImages.numberOfItems==0{savedImages.addItem(withTitle:"No saved images")}
  imageSummary?.stringValue="\(saved.count) saved · \(images.count) to upload · \(removedImages.count) to remove · Save to apply";refresh()
 }
 @objc func savedImageChanged(){refresh()}
 @objc func removeSavedImage(){guard !busy,let id=savedImages.selectedItem?.representedObject as? String else{return};removedImages.append(id);updateImages()}

 func discardEdits()->Bool{guard let song=selectedSong else{return true};if editNotes.string == (song["notes"] as? String ?? "") && editLesson.stringValue == (song["lessonUrl"] as? String ?? "") && images.isEmpty && removedImages.isEmpty{return true};let alert=NSAlert();alert.messageText="Discard unsaved edits?";alert.informativeText="Save this song first to keep your notes, link and pending images.";alert.addButton(withTitle:"Keep Editing");alert.addButton(withTitle:"Discard");return alert.runModal() == .alertSecondButtonReturn}
 func tableView(_ tableView:NSTableView,shouldSelectRow row:Int)->Bool{return (selectedSong == nil || !busy) && (row==tableView.selectedRow || discardEdits())}
 @objc func loadLibrary(){if discardEdits(){selectedSong=nil;images=[];removedImages=[];runAction("list")}}
 @objc func saveSong(){guard selectedSong != nil else{return};runAction("edit")}
 @objc func chooseImages(){let panel=NSOpenPanel();panel.allowedFileTypes=["png","jpg","jpeg","heic","webp"];panel.allowsMultipleSelection=true;panel.canChooseDirectories=false;if panel.runModal() == .OK{for url in panel.urls where !images.contains(url.path){images.append(url.path)};updateImages()}}
 @objc func clearImages(){images=[];removedImages=[];updateImages()}
 func setupMenu(){let menu=NSMenu();let item=NSMenuItem();menu.addItem(item);let app=NSMenu();app.addItem(withTitle:"About Song Studio",action:#selector(NSApplication.orderFrontStandardAboutPanel(_:)),keyEquivalent:"");app.addItem(NSMenuItem.separator());app.addItem(withTitle:"Quit Song Studio",action:#selector(NSApplication.terminate(_:)),keyEquivalent:"q");item.submenu=app;let edit=NSMenuItem();menu.addItem(edit);let submenu=NSMenu(title:"Edit");for(title,action,key) in [("Cut",#selector(NSText.cut(_:)),"x"),("Copy",#selector(NSText.copy(_:)),"c"),("Paste",#selector(NSText.paste(_:)),"v"),("Select All",#selector(NSText.selectAll(_:)),"a")]{submenu.addItem(withTitle:title,action:action,keyEquivalent:key)};edit.submenu=submenu;NSApp.mainMenu=menu}
 func controlTextDidChange(_ notification:Notification){refresh()}
 @objc func optionsChanged(){refresh()}
 func refresh(){if !connected{target.isEnabled = !busy;password.isEnabled = !busy;test?.isEnabled = !busy;if busy{spinner?.startAnimation(nil)}else{spinner?.stopAnimation(nil)};return};clearPending?.isEnabled = !busy;savedImages.isEnabled = !busy && selectedSong != nil;removeImage?.isEnabled = !busy && savedImages.selectedItem?.representedObject != nil;saveEdit?.isEnabled = !busy && selectedSong != nil;refreshLibrary?.isEnabled = !busy;addImage?.isEnabled = !busy && selectedSong != nil;editLesson.isEnabled = !busy && selectedSong != nil;editNotes.isEditable = !busy && selectedSong != nil;tabs?.isEnabled = !busy;songTable.isEnabled = !busy;let value=name.stringValue.isEmpty ? "Song":name.stringValue;preview.stringValue=value+".pdf\n"+value+"-original.mp3\n"+value+"-backing.mp3";start.isEnabled = !busy && !url.stringValue.isEmpty && !name.stringValue.trimmingCharacters(in:.whitespaces).isEmpty && !pdf.isEmpty;for v in [url,name,target,password]{v.isEnabled = !busy};choose.isEnabled = !busy;test?.isEnabled = !busy;replace.isEnabled = !busy;autoImport.isEnabled = !busy;analyze.isEnabled = !busy && autoImport.state == .on;capo.isEnabled = !busy && autoImport.state == .on && analyze.state == .on;cancel.isHidden = !busy;files.isHidden=output.isEmpty;let current=stages.firstIndex(of:stage) ?? -1;for(i,v) in steps.enumerated(){let title=["Connect to Pi","Download audio","Create backing","Send three files","Import & analyze"][i];let done=stage=="done" && (action=="create" || i==0) || current>i;v.stringValue=(done ? "✓  ":current==i ? "→  ":"○  ")+title;v.textColor=done ? green:current==i ? gold:muted};if busy{spinner.startAnimation(nil)}else{spinner.stopAnimation(nil)}}
 @objc func choosePDF(){let panel=NSOpenPanel();panel.allowedFileTypes=["pdf"];panel.allowsMultipleSelection=false;panel.canChooseDirectories=false;if panel.runModal() == .OK,let file=panel.url{pdf=file.path;pdfLabel.stringValue=file.lastPathComponent;if name.stringValue.isEmpty{name.stringValue=file.deletingPathExtension().lastPathComponent.replacingOccurrences(of:"(?i)[ _-]+chords?([ _-]+simple)?$",with:"",options:.regularExpression)};refresh()}}
 @objc func testConnection(){runAction("test")}
 @objc func createSong(){runAction("create")}
 func runAction(_ requested:String){guard !busy else{return};window.makeFirstResponder(nil);action=requested;busy=true;testing=requested=="test";stage="connect";output="";log="";buffer="";status.stringValue=testing ? "Connecting to your Pi…":requested=="list" ? "Loading songs from the Pi…":requested=="edit" ? "Saving on the Pi…":"Starting your song…";status.textColor = .white;refresh();UserDefaults.standard.set(target.stringValue,forKey:"PiTarget")
  let candidates=["/Library/Frameworks/Python.framework/Versions/3.12/bin/python3","/opt/homebrew/bin/python3.12","/usr/local/bin/python3.12","/opt/homebrew/bin/python3.11","/usr/local/bin/python3.11"]
  guard let python=candidates.first(where:{FileManager.default.isExecutableFile(atPath:$0)}),let resources=Bundle.main.resourceURL else{fail("Python 3.11 or 3.12 is required on this Mac.");return}
  let task=Process(),lines=Pipe(),input=Pipe();task.executableURL=URL(fileURLWithPath:python);task.arguments=["-u",resources.appendingPathComponent("worker.py").path];task.standardOutput=lines;task.standardError=lines;task.standardInput=input;var env=ProcessInfo.processInfo.environment;env["PATH"]="/Library/Frameworks/Python.framework/Versions/3.12/bin:/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin:"+(env["PATH"] ?? "");env["PYTHONUNBUFFERED"]="1";env["PYTHONDONTWRITEBYTECODE"]="1";task.environment=env
  var config:[String:Any]=["action":requested,"url":url.stringValue,"pdf":pdf,"name":name.stringValue,"target":target.stringValue,"password":password.stringValue,"capo":capo.indexOfSelectedItem,"import":autoImport.state == .on,"analyze":analyze.state == .on,"replace":replace.state == .on]
  if requested=="edit",let song=selectedSong{config["songId"]=song["id"];config["notes"]=editNotes.string;config["lessonUrl"]=editLesson.stringValue;config["expectedUpdated"]=song["updated"];config["images"]=images;config["removeImages"]=removedImages}

  lines.fileHandleForReading.readabilityHandler={handle in let data=handle.availableData;if data.isEmpty{return};let text=String(decoding:data,as:UTF8.self);DispatchQueue.main.async{self.buffer += text.replacingOccurrences(of:"\r",with:"\n");while let range=self.buffer.range(of:"\n"){let line=String(self.buffer[..<range.lowerBound]);self.buffer.removeSubrange(..<range.upperBound);self.receive(line)}}}
  task.terminationHandler={task in DispatchQueue.main.asyncAfter(deadline:.now()+0.15){lines.fileHandleForReading.readabilityHandler=nil;if !self.buffer.isEmpty{self.receive(self.buffer);self.buffer=""};self.busy=false;self.process=nil;self.pipe=nil;if !["done","error","cancelled"].contains(self.stage){self.fail("The process stopped. Open details for the message.")};self.refresh();if self.stage=="done" && self.testing && !self.connected{self.showMain()}}}
  do{try task.run();process=task;pipe=lines;let data=try JSONSerialization.data(withJSONObject:config);input.fileHandleForWriting.write(data);input.fileHandleForWriting.closeFile()}catch{fail(error.localizedDescription)}
 }
 func receive(_ line:String){guard line.hasPrefix("GPL_EVENT "),let data=line.dropFirst(10).data(using:.utf8),let event=(try? JSONSerialization.jsonObject(with:data)) as? [String:Any],let type=event["type"] as? String else{appendLog(line);return};if let text=event["message"] as? String{status.stringValue=text};switch type{case "library":songs=event["songs"] as? [[String:Any]] ?? [];songTable.reloadData();if songs.isEmpty{selectedSong=nil;editTitle.stringValue="No songs in the Pi library";editNotes.string="";editLesson.stringValue="";images=[];removedImages=[];updateImages()};if !songs.isEmpty{songTable.selectRowIndexes(IndexSet(integer:0),byExtendingSelection:false);selectedSong=songs[0];renderEdit()};case "song":if let updated=event["song"] as? [String:Any]{if let index=songs.firstIndex(where:{$0["id"] as? String == updated["id"] as? String}){songs[index]=updated};selectedSong=updated;if let uploaded=event["uploaded"] as? String{images.removeAll{$0==uploaded}};if let removed=event["removed"] as? String{removedImages.removeAll{$0==removed}};updateImages()};case "progress":stage=event["stage"] as? String ?? stage;case "output":output=event["path"] as? String ?? "";case "error":stage="error";status.textColor = .systemOrange;appendLog(status.stringValue);showDetails();case "cancelled":stage="cancelled";case "complete":stage="done";let warnings=event["warnings"] as? [String] ?? [];if !warnings.isEmpty{status.stringValue += "\n"+warnings.joined(separator:"\n");status.textColor = .systemOrange;appendLog(status.stringValue)}else{status.textColor=green};output=event["output"] as? String ?? output;default:break};refresh()}
 func appendLog(_ text:String){guard !text.isEmpty else{return};log += text+"\n";if log.count>35000{log=String(log.suffix(28000))};logText?.string=log;logText?.scrollToEndOfDocument(nil)}
 func fail(_ text:String){busy=false;stage="error";status.stringValue=text;status.textColor = .systemOrange;appendLog(text);refresh()}
 @objc func cancelJob(){guard let task=process else{return};status.stringValue="Cancelling…";if kill(-task.processIdentifier,SIGTERM) != 0{task.terminate()}}
 @objc func showFiles(){if !output.isEmpty{NSWorkspace.shared.open(URL(fileURLWithPath:output))}}
 @objc func showDetails(){if let details=logsWindow{details.makeKeyAndOrderFront(nil);return};let details=NSWindow(contentRect:NSRect(x:0,y:0,width:700,height:360),styleMask:[.titled,.closable,.resizable],backing:.buffered,defer:false);details.title="Song Studio · Processing details";details.appearance=NSAppearance(named:.darkAqua);details.isReleasedWhenClosed=false;let scroll=NSScrollView(frame:details.contentView!.bounds);scroll.autoresizingMask=[.width,.height];scroll.hasVerticalScroller=true;let text=NSTextView(frame:scroll.bounds);text.isVerticallyResizable=true;text.isHorizontallyResizable=false;text.autoresizingMask=[.width];text.textContainer?.widthTracksTextView=true;text.isEditable=false;text.font=NSFont.monospacedSystemFont(ofSize:11,weight:.regular);text.backgroundColor=bg;text.textColor = .white;text.string=log;scroll.documentView=text;details.contentView!.addSubview(scroll);logText=text;logsWindow=details;details.center();details.makeKeyAndOrderFront(nil)}
 func windowWillClose(_ notification:Notification){if let closing=notification.object as? NSWindow,closing===window{NSApp.terminate(nil)}}
 func applicationShouldHandleReopen(_ sender:NSApplication,hasVisibleWindows flag:Bool)->Bool{window.makeKeyAndOrderFront(nil);return true}
 func applicationShouldTerminateAfterLastWindowClosed(_ sender:NSApplication)->Bool{return true}
 func applicationShouldTerminate(_ sender:NSApplication)->NSApplication.TerminateReply{if !busy && !discardEdits(){return .terminateCancel};if busy{let alert=NSAlert();alert.messageText="Cancel the current song?";alert.informativeText="Completed Mac files will be kept.";alert.addButton(withTitle:"Cancel & Quit");alert.addButton(withTitle:"Keep Working");if alert.runModal() != .alertFirstButtonReturn{window.makeKeyAndOrderFront(nil);return .terminateCancel};cancelJob()};return .terminateNow}
}
